                 day:"2025-04-02", units:7};

test("Studio admission preserves replay, conflict, cancellation and tenant/day accounting", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(request), {status:"booked", id:"morning", remaining:1});
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units:8}).status, "conflict");
  assert.deepEqual(dispatch({...request, id:"evening", units:2}),
                   {status:"full", id:"evening", remaining:1});
  assert.equal(dispatch({...request, id:"other-day", day:"2025-04-03"}).status, "booked");
  assert.equal(dispatch({...request, id:"other-tenant", tenant:"lily", units:5}).status, "booked");
  assert.equal(dispatch({...request, id:"fallback-full", tenant:"lily", units:1}).status, "full");
  assert.equal(dispatch({...request, id:"lower-quota", tenant:"iris", units:4}).status, "full");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"morning"}).status, "cancelled");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"morning"}).status, "replay");
  assert.equal(dispatch(request).status, "cancelled");
  assert.deepEqual(dispatch({...request, id:"replacement", units:8}),
                   {status:"booked", id:"replacement", remaining:0});
  assert.equal(dispatch({service:"studio", action:"usage", tenant:"orchid", day:request.day}).units, 8);
  assert.equal(dispatch({...request, service:"archive"}).status, "full");
  assert.equal(dispatch({...request, service:"archive", units:5}).status, "booked");
});

