  assert.deepEqual(dispatch(renewal), {status:"booked", id:"may", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:8}).status, "conflict");
  assert.equal(dispatch({...renewal, id:"may-full", units:2}).status, "full");
  assert.equal(dispatch({...renewal, id:"june-full", day:"2025-06-02", units:9}).status, "full");
  dispatch({service:"studio", action:"cancel", id:"may"});
  assert.equal(dispatch(renewal).status, "cancelled");
  assert.equal(dispatch({...renewal, previous:"may", id:"june", day:"2025-06-02"}).status, "missing");
  dispatch({...request, id:"default", tenant:"lily", units:5});
  assert.equal(dispatch({...renewal, previous:"default", id:"default-renew", units:6}).status, "full");
  assert.equal(dispatch({...renewal, previous:"default", id:"default-renew"}).status, "booked");
