import {renew} from "../common/renewals.mjs";
import {booking} from "../common/request.mjs";

export function studioCapacity(catalog, tenant) {
  return catalog.studios.get(tenant) ?? catalog.default;
}

// Keep Studio admission local; the shared journal still owns existing IDs and
// accounts for every active entry, including imports, on the tenant's day.
function reserveStudio(ledger, request, catalog) {
  if (ledger.inspect(request.id)) return ledger.reserve(request);
  const cap = studioCapacity(catalog, request.tenant);
  const used = ledger.usage(request.tenant, request.day);
  if (used + request.units > cap) {
    return {status: "full", id: request.id, remaining: Math.max(0, cap - used)};
  }
  ledger.post(request);
  return {status: "booked", id: request.id, remaining: cap - used - request.units};
}

export function bookStudio(ledger, input, catalog = ledger.catalog) {
  return reserveStudio(ledger, booking(input), catalog);
}

export function renewStudio(ledger, operation, catalog = ledger.catalog) {
  // Reuse renewal validation and inheritance, with Studio admission for the next
  // reservation rather than the shared desk's default-capacity admission.
  return renew({
    inspect: id => ledger.inspect(id),
    reserve: request => reserveStudio(ledger, request, catalog)
  }, operation);
}
